#!/usr/bin/env node
// Bundles SKILL.md files from Agent-zero-pentest into data/skills.js
// Preserves existing metadata (name, category, tags, description) and populates the body field.
const fs = require('fs');
const path = require('path');

const srcDir = 'C:/Users/jaime/Agent-zero-pentest/patches/plugins/_pentest_kit/skills';
const skillsFile = path.join(__dirname, '..', 'data', 'skills.js');

// Read existing skills.js to get metadata
const existingSrc = fs.readFileSync(skillsFile, 'utf8');

// Parse existing VOID_SKILLS by running it in a sandbox
const vm = require('vm');
const sandbox = { window: {} };
vm.createContext(sandbox);
vm.runInContext(existingSrc, sandbox);
const existingSkills = sandbox.window.VOID_SKILLS || {};

// Read all SKILL.md files
const dirs = fs.readdirSync(srcDir).filter(d =>
  fs.statSync(path.join(srcDir, d)).isDirectory()
);

let updated = 0;
for (const slug of dirs) {
  const mdPath = path.join(srcDir, slug, 'SKILL.md');
  if (!fs.existsSync(mdPath)) {
    console.log('  SKIP ' + slug + ' (no SKILL.md)');
    continue;
  }
  const body = fs.readFileSync(mdPath, 'utf8').trim();
  if (existingSkills[slug]) {
    existingSkills[slug].body = body;
    updated++;
    const lines = body.split('\n').length;
    console.log('  OK   ' + slug + ' (' + lines + ' lines)');
  } else {
    console.log('  NEW  ' + slug + ' (not in existing skills.js — skipped)');
  }
}

// Write back
let out = '// data/skills.js \u2014 32 pentesting skill methodologies\n';
out += '// Full skill bodies from Agent-zero-pentest SKILL.md files\n';
out += '// Generated by scripts/bundle-skills.js\n\n';
out += 'window.VOID_SKILLS = ' + JSON.stringify(existingSkills, null, 2) + ';\n';

fs.writeFileSync(skillsFile, out, 'utf8');

console.log('\nWritten to ' + skillsFile);
console.log('Updated: ' + updated + ' skills with methodology bodies');
console.log('File size: ' + (fs.statSync(skillsFile).size / 1024).toFixed(0) + ' KB');
